package com.nightbeam.donutshards.zone;import org.junit.jupiter.api.Test;import java.util.UUID;import static org.assertj.core.api.Assertions.*;class ZoneServiceTest{@Test void tracksMembership(){var service=new ZoneService();var id=UUID.randomUUID();assertThat(service.isInZone(id)).isFalse();service.enter(id,"glaze-ring");assertThat(service.current(id)).contains("glaze-ring");service.leave(id);assertThat(service.current(id)).isEmpty();}}
